  configurable: false,
  enumerable: false,
  writable: false,
  value: 2
});

assert.sameValue(result, true, "result === true");

verifyEqualTo(target, "attr", 2);
verifyProperty(target, "attr", {
  writable: false,
  enumerable: false,
  configurable: false,
});
}
